{
  "items": [
    {
      "name": "MvPolynomial.sum_def",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] {A : Type u_2} [inst_1 : AddCommMonoid A] {p : MvPolynomial σ R}\n  {b : (σ →₀ ℕ) → R → A}, Finsupp.sum p b = ∑ m ∈ p.support, b m (MvPolynomial.coeff m p)"
    },
    {
      "name": "MvPolynomial.coeffs",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset R"
    },
    {
      "name": "Polynomial.card_mahlerMeasure_le_prod",
      "module_name": "Mathlib.NumberTheory.MahlerMeasure",
      "kind": "theorem",
      "type": "∀ (n : ℕ) (B : NNReal),\n  {p | p.natDegree ≤ n ∧ (Polynomial.map (Int.castRingHom ℂ) p).mahlerMeasure ≤ ↑B}.ncard ≤\n    ∏ i, (2 * ⌊↑(n.choose ↑i) * B⌋₊ + 1)"
    },
    {
      "name": "Polynomial.card_support_mul_le",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p q : Polynomial R}, (p * q).support.card ≤ p.support.card * q.support.card"
    },
    {
      "name": "MvPolynomial.support",
      "module_name": "Mathlib.Algebra.MvPolynomial.Basic",
      "kind": "definition",
      "type": "{R : Type u} → {σ : Type u_1} → [inst : CommSemiring R] → MvPolynomial σ R → Finset (σ →₀ ℕ)"
    }
  ]
}
